//! Ramps whose ends are nearly equal, steep, very short and very long, against
//! figures from 80-digit decimal arithmetic.
//!
//! `stability/figures.rs` is generated by `stability/reference_figures.py`,
//! which evaluates the segment definitions with Python's `decimal`. It shares
//! no code with the map, so a cancellation in the map's forms shows as an
//! error here. The pure-Rust `libm` makes the figures hold on any platform.
//!
//! "

mod common;
#[path = "stability/figures.rs"]
mod figures;

use common::pt;
use tutti_tempo::{Shape, TempoMap};
use tutti_types::{Beat, Seconds};

/// One ramp and its rows: (beat in, seconds out, seconds in, beat out).
struct Case {
    name: &'static str,
    ramp_beats: bool,
    from: f64,
    to: f64,
    span: f64,
    rows: &'static [(f64, f64, f64, f64)],
}

/// Relative error allowed against the decimal figure: a few ulps.
const REL: f64 = 8e-15;

fn close(got: f64, want: f64) -> bool {
    if want == 0.0 {
        got == 0.0
    } else {
        (got - want).abs() <= REL * want.abs()
    }
}

/// Forward (beat to seconds) and inverse (seconds to beat), both shapes, on
/// nearly equal, steep, very short and very long ramps. Offset 0 takes the
/// guarded `x == 0.0` and `y == 0.0` branches and must be exactly 0.
#[test]
fn ramps_match_decimal_figures() {
    for case in figures::CASES {
        let shape = if case.ramp_beats {
            Shape::RampBeats
        } else {
            Shape::RampTime
        };
        let map = TempoMap::new([
            pt(0.0, case.from, shape),
            pt(case.span, case.to, Shape::Step),
        ])
        .unwrap();
        for &(beat_in, sec_out, sec_in, beat_out) in case.rows {
            let got = map.seconds_at(Beat(beat_in)).get();
            assert!(
                close(got, sec_out),
                "{} {shape:?} seconds_at({beat_in}) = {got:e}, want {sec_out:e}",
                case.name
            );
            let got = map.beat_at_seconds(Seconds(sec_in)).get();
            assert!(
                close(got, beat_out),
                "{} {shape:?} beat_at_seconds({sec_in}) = {got:e}, want {beat_out:e}",
                case.name
            );
        }
    }
}
